// Ein Element pro E-Mail: Felder normalisieren, Anhänge als Base64 anhängen
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  const from = (j.from && j.from.value && j.from.value[0]) || {};
  const attachments = [];
  for (const key of Object.keys(items[i].binary || {})) {
    const b = items[i].binary[key];
    const buf = await this.helpers.getBinaryDataBuffer(i, key);
    if (buf.length > 15 * 1024 * 1024) continue;
    attachments.push({ filename: b.fileName || key, mimeType: b.mimeType, contentBase64: buf.toString('base64') });
  }
  const subject = j.subject || '';
  const fromEmail = (from.address || '').toLowerCase();
  // Benachrichtigung des Kontaktformulars liegt schon im Panel, Abwesenheitsnotizen brauchen keine Antwort
  const auto = String((j.headers && (j.headers['auto-submitted'] || j.headers['x-autoreply'])) || '').toLowerCase();
  if (/^neue kontaktanfrage von/i.test(subject) && fromEmail.startsWith('noreply@')) continue;
  if (auto && auto !== 'no') continue;
  if (/^(mailer-daemon|postmaster)@/i.test(fromEmail)) continue;
  out.push({ json: {
    messageId: j.messageId,
    inReplyTo: j.inReplyTo,
    references: j.references,
    fromName: from.name || '',
    fromEmail,
    to: (j.to && j.to.text) || '',
    subject,
    text: j.text || '',
    html: typeof j.html === 'string' ? j.html : '',
    date: j.date,
    attachments,
  }});
}
return out;
